-- The DR-TWIST code key (Code keys -> Drilling -> DR-TWIST), from the ISCAR
-- e-catalog's DR-TWIST families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.drtwist', $ck${"title": "DR-TWIST code key – indexable insert drills and inserts", "subtitle": "DR indexable insert drills (12 – 80 mm, 2xD – 5xD) with square SOMT / SOMX inserts, and their XOMT / AOMT / SOGX inserts", "example": "DR120-036-16-04-3D-N", "decoder": "dr-twist", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "SOMT", "rows": [{"code": "SOMT", "meaning": "Square inserts for DR drills"}, {"code": "SOMX", "meaning": "Square precision inserts for DR drills"}, {"code": "SOGX", "meaning": "Ground square inserts for aluminum"}, {"code": "SOGT", "meaning": "Ground square inserts for aluminum"}, {"code": "XOMT", "meaning": "Inserts for DR drills and boring bars"}, {"code": "AOMT", "meaning": "Inserts for DR drills"}, {"code": "AOGT", "meaning": "Ground inserts for DR drills (aluminum)"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "##", "meaning": "Insert size (cutting edge length, mm)"}]}, {"key": "i-thick", "title": "Insert – thickness", "rows": [{"code": "##", "meaning": "Insert thickness code (e.g. 02, 04, 05)"}, {"code": "#T#", "meaning": "Insert thickness code with T (e.g. T3 = 3.97 mm)"}]}, {"key": "i-radius", "title": "Insert – corner radius", "rows": [{"code": "##", "meaning": "Corner radius x10 (e.g. 04 = 0.4 mm)"}]}, {"key": "i-angle", "title": "Insert – angle", "rows": [{"code": "##", "meaning": "Insert angle (e.g. 90)"}]}, {"key": "i-chip", "title": "Insert – chipformer", "sample": "DT", "rows": [{"code": "DT", "meaning": "General applications at medium to high feeds"}, {"code": "GF", "meaning": "Soft materials at low to medium feeds"}, {"code": "HD", "meaning": "Carbon steel and soft materials"}, {"code": "AL", "meaning": "Aluminum"}]}, {"key": "t-family", "title": "Drill – family", "sample": "DR", "rows": [{"code": "DR", "meaning": "Indexable square insert drill with coolant holes"}]}, {"key": "t-dia", "title": "Drill – diameter", "sample": "120", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 120 = 12.0 mm)"}, {"code": "0##", "meaning": "Drilling diameter in mm from 26 mm (e.g. 030 = 30 mm)"}]}, {"key": "t-length", "title": "Drill – length", "rows": [{"code": "###", "meaning": "Usable length in mm (inferred)"}]}, {"key": "t-height", "title": "Drill – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (16 – 50)"}]}, {"key": "t-insert", "title": "Drill – insert size", "rows": [{"code": "##", "meaning": "Size of the inserts it carries (e.g. 04 = SOMT 04...)"}]}, {"key": "t-depth", "title": "Drill – drilling depth", "rows": [{"code": "#D", "meaning": "Drilling depth ratio (2D – 5D)"}]}, {"key": "t-type", "title": "Drill – type", "sample": "N", "rows": [{"code": "N", "meaning": "For rotating applications (machining centers)"}, {"code": "T", "meaning": "For non-rotating applications (lathes)"}, {"code": "CA", "meaning": "Large diameter drill with cartridges (DR-CA, 57 – 80 mm)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
